from pathlib import Path

# --- app.py: return Inspector HWND and foreground it from the CRM process ---
p = Path('ZakazkyApp_base_6.1/app.py')
s = p.read_text(encoding='utf-8')
old = '''# The Inspector may lose foreground while CRM finishes its synchronous call.\n# Activate the completed draft once more so it is immediately visible to user.\ntry {\n  $mail.GetInspector.Activate()\n} catch {}\n\"\"\"\n        try:\n            r=subprocess.run([\"powershell.exe\",\"-NoProfile\",\"-STA\",\"-Command\",ps],\n                             env=env,capture_output=True,text=True,timeout=20,\n                             creationflags=getattr(subprocess,\"CREATE_NO_WINDOW\",0))\n            if r.returncode==0:return True\n'''
new = '''# Return the exact Inspector HWND to the CRM process. Calling Activate() only\n# inside this PowerShell child is not sufficient on Windows because foreground\n# activation may be refused for a non-foreground child process.\ntry {\n  $insp=$mail.GetInspector\n  $insp.Activate()\n  Write-Output (\"TURTO_OUTLOOK_HWND=\" + [string]$insp.HWND)\n} catch {}\n\"\"\"\n        try:\n            r=subprocess.run([\"powershell.exe\",\"-NoProfile\",\"-STA\",\"-Command\",ps],\n                             env=env,capture_output=True,text=True,timeout=20,\n                             creationflags=getattr(subprocess,\"CREATE_NO_WINDOW\",0))\n            if r.returncode==0:\n                # CRM itself is the foreground process that initiated the user action,\n                # so let CRM bring the exact Outlook Inspector to the foreground.\n                try:\n                    m=re.search(r'TURTO_OUTLOOK_HWND=(\\d+)',r.stdout or '')\n                    if m:\n                        hwnd=int(m.group(1))\n                        try:\n                            import win32con,win32gui\n                            if win32gui.IsWindow(hwnd):\n                                win32gui.ShowWindow(hwnd,win32con.SW_RESTORE)\n                                win32gui.SetWindowPos(\n                                    hwnd,win32con.HWND_TOP,0,0,0,0,\n                                    win32con.SWP_NOMOVE|win32con.SWP_NOSIZE|win32con.SWP_SHOWWINDOW)\n                                try:win32gui.BringWindowToTop(hwnd)\n                                except Exception:pass\n                                try:win32gui.SetForegroundWindow(hwnd)\n                                except Exception:pass\n                                # If Windows focus-lock still refuses the foreground call,\n                                # pulse topmost and use SwitchToThisWindow as a final fallback.\n                                if win32gui.GetForegroundWindow()!=hwnd:\n                                    try:\n                                        win32gui.SetWindowPos(hwnd,win32con.HWND_TOPMOST,0,0,0,0,win32con.SWP_NOMOVE|win32con.SWP_NOSIZE)\n                                        win32gui.SetWindowPos(hwnd,win32con.HWND_NOTOPMOST,0,0,0,0,win32con.SWP_NOMOVE|win32con.SWP_NOSIZE|win32con.SWP_SHOWWINDOW)\n                                    except Exception:pass\n                                    try:\n                                        import ctypes\n                                        ctypes.windll.user32.SwitchToThisWindow(hwnd,True)\n                                    except Exception:pass\n                        except Exception:\n                            try:\n                                import ctypes\n                                user32=ctypes.windll.user32\n                                user32.ShowWindow(hwnd,9)\n                                user32.BringWindowToTop(hwnd)\n                                if not user32.SetForegroundWindow(hwnd):\n                                    user32.SwitchToThisWindow(hwnd,True)\n                            except Exception:pass\n                except Exception:pass\n                return True\n'''
if old not in s:
    raise SystemExit('app foreground block not found')
s = s.replace(old, new, 1)
p.write_text(s, encoding='utf-8')

# --- post_baseline.py: safe cleanup of legacy persistent mail staging ---
p = Path('post_baseline.py')
s = p.read_text(encoding='utf-8')
marker = '''    def show_offer_archive_folder(app, folders):\n'''
if marker not in s:
    raise SystemExit('post_baseline Explorer marker not found')
cleanup = '''    def cleanup_legacy_offer_staging(app=None):\n        \"\"\"Delete only legacy staging files whose full bytes are already stored in DB.\n\n        Current MSG/PDF import uses TemporaryDirectory and cleans itself. Older\n        versions could leave mail material under DATA_ROOT\\Dokumenty/Documents.\n        Never remove an unknown file and never touch the configured offer archive.\n        \"\"\"\n        try:\n            import os\n\n            data_root = Path(getattr(M, 'DATA_ROOT', ''))\n            if not data_root.is_dir():\n                return 0\n\n            roots = []\n            try:\n                for child in data_root.iterdir():\n                    if child.is_dir() and child.name.casefold() in {'dokumenty', 'documents'}:\n                        roots.append(child)\n            except Exception:\n                return 0\n            if not roots:\n                return 0\n\n            # A file is disposable only when the database already contains its\n            # complete original bytes, not merely metadata or a path.\n            known_hashes = set()\n            try:\n                with M.db() as con:\n                    tables = {\n                        str(row[0])\n                        for row in con.execute(\n                            \"SELECT name FROM sqlite_master WHERE type='table'\"\n                        ).fetchall()\n                    }\n                    if 'offer_source_messages' in tables:\n                        cols = {\n                            str(row[1])\n                            for row in con.execute(\n                                'PRAGMA table_info(offer_source_messages)'\n                            ).fetchall()\n                        }\n                        if 'source_blob' in cols:\n                            known_hashes.update(\n                                str(row[0])\n                                for row in con.execute(\n                                    \"SELECT source_hash FROM offer_source_messages \"\n                                    \"WHERE source_blob IS NOT NULL AND length(source_blob)>0 \"\n                                    \"AND trim(coalesce(source_hash,''))<>''\"\n                                ).fetchall()\n                            )\n                    if 'offer_source_attachments' in tables:\n                        known_hashes.update(\n                            str(row[0])\n                            for row in con.execute(\n                                \"SELECT content_hash FROM offer_source_attachments \"\n                                \"WHERE content_blob IS NOT NULL AND length(content_blob)>0 \"\n                                \"AND trim(coalesce(content_hash,''))<>''\"\n                            ).fetchall()\n                        )\n            except Exception:\n                return 0\n            if not known_hashes:\n                return 0\n\n            try:\n                archive = archive_root(app).resolve()\n            except Exception:\n                archive = None\n\n            def digest(path):\n                h = hashlib.sha256()\n                with path.open('rb') as handle:\n                    while True:\n                        chunk = handle.read(1024 * 1024)\n                        if not chunk:\n                            break\n                        h.update(chunk)\n                return h.hexdigest()\n\n            deleted = 0\n            for root in roots:\n                try:\n                    resolved_root = root.resolve()\n                    if archive is not None and (\n                        resolved_root == archive\n                        or resolved_root in archive.parents\n                        or archive in resolved_root.parents\n                    ):\n                        # Never clean a path that is or contains the real archive.\n                        continue\n                except Exception:\n                    continue\n\n                files = []\n                try:\n                    files = [p for p in root.rglob('*') if p.is_file() and not p.is_symlink()]\n                except Exception:\n                    pass\n                for file_path in files:\n                    try:\n                        if digest(file_path) in known_hashes:\n                            file_path.unlink()\n                            deleted += 1\n                    except Exception:\n                        pass\n\n                # Remove only directories that became genuinely empty. Unknown\n                # content keeps both its file and its parent folder untouched.\n                try:\n                    dirs = [p for p in root.rglob('*') if p.is_dir()]\n                    dirs.sort(key=lambda p: len(p.parts), reverse=True)\n                    for directory in dirs:\n                        try:\n                            if not any(directory.iterdir()):\n                                directory.rmdir()\n                        except Exception:\n                            pass\n                    if root.exists() and not any(root.iterdir()):\n                        root.rmdir()\n                except Exception:\n                    pass\n            return deleted\n        except Exception:\n            return 0\n\n    M.cleanup_legacy_offer_staging = cleanup_legacy_offer_staging\n\n'''
s = s.replace(marker, cleanup + marker, 1)

old_finish = '''            if state['archives'] and not state['cancel']:\n                show_offer_archive_folder(self, state['archives'])\n'''
new_finish = '''            try:\n                cleanup_legacy_offer_staging(self)\n            except Exception:\n                pass\n            if state['archives'] and not state['cancel']:\n                show_offer_archive_folder(self, state['archives'])\n'''
if old_finish not in s:
    raise SystemExit('batch finish marker not found')
s = s.replace(old_finish, new_finish, 1)

old_init = '''        try:\n            self.after(1200, lambda: reclaim_tree_layout(self))\n        except Exception:\n            pass\n        return result\n'''
new_init = '''        try:\n            self.after(1200, lambda: reclaim_tree_layout(self))\n        except Exception:\n            pass\n        try:\n            # One safe pass also removes verified leftovers from older releases.\n            self.after(1800, lambda: cleanup_legacy_offer_staging(self))\n        except Exception:\n            pass\n        return result\n'''
if old_init not in s:
    raise SystemExit('post_baseline init marker not found')
s = s.replace(old_init, new_init, 1)
p.write_text(s, encoding='utf-8')

# --- v631: direct Outlook/file route also runs the safe cleanup ---
p = Path('ZakazkyApp_base_6.1/v631_diskdrop.py')
s = p.read_text(encoding='utf-8')
old = '''        if archive_folders:\n            try:\n                opener = getattr(M, 'show_offer_archive_folder', None)\n                if callable(opener):\n                    opener(app, archive_folders)\n            except Exception:\n                pass\n        return good\n'''
new = '''        if archive_folders:\n            try:\n                opener = getattr(M, 'show_offer_archive_folder', None)\n                if callable(opener):\n                    opener(app, archive_folders)\n            except Exception:\n                pass\n        try:\n            cleanup = getattr(M, 'cleanup_legacy_offer_staging', None)\n            if callable(cleanup):\n                cleanup(app)\n        except Exception:\n            pass\n        return good\n'''
if old not in s:
    raise SystemExit('v631 direct cleanup marker not found')
s = s.replace(old, new, 1)
p.write_text(s, encoding='utf-8')

Path('release_version.txt').write_text('6.3.14\n', encoding='utf-8')
Path('release_notes.txt').write_text(
    '• Outlook koncept Poptávky nyní vrací CRM přesné HWND svého Inspector okna. Do popředí jej následně přepíná přímo proces CRM pomocí Win32; při omezení foreground aktivace se použije krátký Z-order/topmost pulse a SwitchToThisWindow fallback.\n'
    '• Současný import MSG/PDF nadále používá systémové TemporaryDirectory a pracovní soubory po dokončení automaticky maže. Trvalá složka TURTO Zakazky\\Dokumenty/Documents není pro aktuální import potřeba.\n'
    '• Přidán bezpečný úklid legacy mail stagingu: smaže pouze soubory v Dokumenty/Documents, jejichž SHA-256 odpovídá původnímu MSG nebo příloze, která už má kompletní BLOB uložený v databázi. Neznámé soubory se nikdy nemažou.\n'
    '• Bezpečný úklid proběhne po zpracování nabídky a jednou po startu, takže lze odstranit i ověřené pozůstatky starších verzí. Konfigurovaný archiv Nabídky je výslovně chráněn a nikdy se tímto úklidem nemaže.\n'
    '• Databázové schéma, parsery, Excel exporty, názvy archivních složek a DB-only mazání Nabídek se nemění.\n',
    encoding='utf-8',
)
